<script setup lang="ts">
import {ref,onMounted} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import AppButton from '@/components/AppButton.vue';import BaseCard from '@/components/BaseCard.vue';import SectionHeader from '@/components/SectionHeader.vue';import StatusTag from '@/components/StatusTag.vue';import Stage1Field from './Stage1Field.vue';import Stage1Status from './Stage1Status.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const p=useStage1Page('profile'),{error,busy,loading,pending,dirty}=p,data=ref<Data|null>(null),change=ref<Data|null>(null),form=ref<Data>({})
function load(){return p.read(async()=>({profile:await stage1Service.profile(),change:await stage1Service.read<Data|null>('/profile-change/current')}),v=>{data.value=v.profile;change.value=v.change;form.value={contactName:v.profile.contactName,phone:v.profile.phone,description:v.profile.description||'',businessHours:v.profile.extra.businessHours||''};dirty.value=false})}
async function save(){await p.write(()=>p.command('/profile',{expectedVersion:data.value?.version,...form.value},'PUT'),()=>{return load()})}
const go=(url:string)=>uni.navigateTo({url})
onMounted(load);onShow(()=>{if(data.value&&!dirty.value&&!pending.value)return load()})
</script>
<template><AppPage secondary :status="loading&&!data?'loading':'ready'"><template #navbar><AppNavbar title="商户资料" centered show-back/></template><view class="s1-profile stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(load)" @retry="p.retry(load)" @abandon="p.abandon(load)"/><BaseCard v-if="data" class="s1-form"><SectionHeader :title="data.storeName"/><StatusTag :tone="data.state==='OPEN'?'success':'error'">{{label(data.state)}}</StatusTag><text v-if="data.closedReason">{{data.closedReason}}</text><text>主体：{{data.legalName}}</text><text>统一社会信用代码：{{data.legalCode}}</text><text>法定代表人：{{data.legalPerson}}</text><text>地址：{{data.address}}</text><text class="s1-copy">当前批准版本 {{data.version}}。主体、店名和范围变更须另行审核。</text><AppButton v-if="p.has('profile.write')" variant="secondary" @click="go('/pages/stores/editor/index')">申请关键资料变更</AppButton><view v-if="change"><StatusTag>{{label(change.status)}}</StatusTag><text class="s1-copy">有一份资料变更记录，当前批准资料继续生效。</text></view></BaseCard><BaseCard v-if="data" class="s1-form"><SectionHeader title="日常联系资料"/><Stage1Field v-model="form.contactName" label="联系人" required :maximum="30" :disabled="busy||pending||!p.has('profile.write')" @update:model-value="dirty=true"/><Stage1Field v-model="form.phone" label="联系电话" required :maximum="20" :disabled="busy||pending||!p.has('profile.write')" @update:model-value="dirty=true"/><Stage1Field v-model="form.businessHours" label="营业时间" :maximum="200" :disabled="busy||pending||!p.has('profile.write')" @update:model-value="dirty=true"/><Stage1Field v-model="form.description" label="店铺介绍" type="textarea" :maximum="500" :disabled="busy||pending||!p.has('profile.write')" @update:model-value="dirty=true"/><AppButton v-if="p.has('profile.write')" :disabled="pending" :loading="busy" @click="save">保存联系资料</AppButton></BaseCard><AppButton variant="quiet" @click="go('/pages/qualifications/index')">资质与续期历史</AppButton><AppButton variant="quiet" :loading="loading" @click="load">重新读取</AppButton></view></AppPage></template><style scoped lang="scss">.s1-profile{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-copy{font-size:13px;color:$color-text-secondary}</style>
